import {Inject, Injectable, Logger} from "@nestjs/common"
import {ExecutionError, TenantTransactionManager, TransactionOptions} from "@services/transaction/interfaces"
import {Prisma} from "@prisma/client"
import {
  ConflictingIsolationLevelError,
  DatabaseClient,
  InvalidOrganizationIdError,
  OrganizationMismatchError,
  TenantContextRequiredError,
  TransactionRetryExhaustedError
} from "./database-client"
import {TenantContext} from "@domain"

import {TaskEither} from "fp-ts/TaskEither"
import * as TE from "fp-ts/TaskEither"
import * as E from "fp-ts/Either"

class TransactionRollbackError<E> extends Error {
  constructor(public readonly errorPayload: E) {
    super("Transaction rolled back explicitly")
    this.name = "TransactionRollbackError"
  }
}

/**
 * Internal type guard for TransactionRollbackError.
 *
 * NOTE: While the generic type <E> is erased at runtime, this check is safe because
 * TransactionRollbackError is not exported and is only instantiated within this module's
 * `execute` method using the `E` of the provided computation.
 */
function isTransactionRollbackError<E extends string>(error: unknown): error is TransactionRollbackError<E> {
  return error instanceof TransactionRollbackError
}

@Injectable()
export class PrismaTransactionManager implements TenantTransactionManager {
  constructor(
    @Inject(DatabaseClient)
    private readonly dbClient: {
      transactional<T>(
        organizationId: string,
        computation: () => Promise<T>,
        options?: {isolationLevel?: Prisma.TransactionIsolationLevel}
      ): Promise<T>
    }
  ) {}

  /**
   * @param context - Trusted organization context established by request or worker admission.
   * @param computation - A function returning a `TaskEither` to be executed transactionally.
   * @param options - Optional configuration for the transaction.
   * @returns The result of the computation.
   */
  execute<E extends string, T>(
    context: TenantContext,
    computation: () => TaskEither<E, T>,
    options?: TransactionOptions
  ): TaskEither<E | ExecutionError, T> {
    return TE.tryCatch(
      async () => {
        return this.dbClient.transactional(
          context.organizationId,
          async () => {
            const result = await computation()()
            if (E.isLeft(result))
              // Reject to rollback the transaction and propagate the error payload
              throw new TransactionRollbackError(result.left)

            return result.right
          },
          {
            isolationLevel: options?.isolationLevel
              ? Prisma.TransactionIsolationLevel[options.isolationLevel]
              : undefined
          }
        )
      },
      (error: unknown) => {
        // Nested service boundaries must let the owning transaction retry the whole computation.
        if (DatabaseClient.isRetryableTransactionError(error)) throw error

        if (error instanceof ConflictingIsolationLevelError) {
          Logger.error("Conflicting isolation level requested.", error)
          return "conflicting_isolation_level" as const
        }

        if (error instanceof InvalidOrganizationIdError) return "invalid_organization_id"
        if (error instanceof TenantContextRequiredError) return "tenant_context_required"
        if (error instanceof OrganizationMismatchError) return "organization_mismatch"
        if (error instanceof TransactionRetryExhaustedError) return "retry_exhausted"

        if (isTransactionRollbackError<E>(error))
          // Extract the exact error payload generated by the computation TaskEither

          return error.errorPayload

        if (
          error instanceof Prisma.PrismaClientKnownRequestError &&
          error.code === "P2028" &&
          /commit/i.test(error.message)
        )
          return "commit_outcome_unknown"

        Logger.error("Database transaction failed.", error)
        return "storage_unavailable"
      }
    )
  }
}
